create table profiles(id uuid primary key references auth.users on delete cascade,display_name text,role text default 'owner',created_at timestamptz default now(),updated_at timestamptz default now());
create table brand_voices(id uuid primary key default gen_random_uuid(),key text unique not null,name text not null,description text not null,instructions text not null,active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table source_materials(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users not null,title text,original_text text not null,source_type text default 'reflection',voice_key text,tags text[] default '{}',sensitivity_level text default 'private',created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz);
create table campaigns(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users not null,source_id uuid references source_materials,name text,objective text,audience text,emotional_directions text[],intensity text,cta text,status text default 'draft',created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz);
create table generated_content(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users not null,campaign_id uuid references campaigns,platform text,content_type text,formula text,generated_text text,edited_text text,metadata jsonb default '{}',is_favorite boolean default false,status text default 'draft',created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz);
alter table source_materials enable row level security;alter table campaigns enable row level security;alter table generated_content enable row level security;
create policy "own sources" on source_materials for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own campaigns" on campaigns for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own content" on generated_content for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
